  publishProcesses(*ui, state);
  g_workers.start([uiHandle = ui]() mutable {
    int lastPct = -1;
    Updater::State lastState = Updater::State::Idle;
    bool upToDateDismissScheduled = false;
    bool failedDismissScheduled = false;
    while (!g_shutdown.stopping()) {
      auto st = Updater::currentState();
      int pct = Updater::downloadPct();
      if (st != lastState || pct != lastPct) {
        lastState = st;
        lastPct = pct;
        std::string statusText;
        std::string versionText = "v" + Updater::info().remoteVersion;
        int stateCode = 1; // checking by default
        int progress = 0;
        bool legacyAvailable = false;
        switch (st) {
          case Updater::State::Idle:
            stateCode = 1; break;
          case Updater::State::Checking:
            stateCode = 1; break;
          case Updater::State::UpToDate:
            stateCode = 2; statusText = "Up to date";
            versionText = "v" + std::string(Updater::kBuildVersion);
            break;
          case Updater::State::UpdateAvailable:
            stateCode = 3; legacyAvailable = true;
            statusText = "Update available";
            break;
          case Updater::State::Downloading:
            stateCode = 4; legacyAvailable = true;
            progress = pct; statusText = "Downloading…";
            break;
          case Updater::State::Ready:
            stateCode = 5; legacyAvailable = true;
            progress = 100; statusText = "Ready";
            break;
          case Updater::State::Failed:
            stateCode = 6; statusText = Updater::lastError();
            if (statusText.empty()) statusText = "Update check failed";
            break;
        }
        onUiThread(
            [uiHandle, stateCode, statusText, versionText,
             legacyAvailable, progress]() {
              uiHandle->set_update_state(stateCode);
              uiHandle->set_update_available(legacyAvailable);
              uiHandle->set_update_version(slint::SharedString(versionText));
              uiHandle->set_update_status(slint::SharedString(statusText));
              uiHandle->set_update_progress(progress);
            });

        if (stateCode == 2 && !upToDateDismissScheduled) {
          upToDateDismissScheduled = true;
          g_workers.start([uiHandle]() mutable {
            if (waitForShutdown(2200)) return;
            onUiThread([uiHandle]() {
              uiHandle->set_update_state(0);
              uiHandle->set_update_available(false);
            });
          });
        }
        if (stateCode != 6) failedDismissScheduled = false;
        if (stateCode == 6 && !failedDismissScheduled) {
          failedDismissScheduled = true;
          g_workers.start([uiHandle]() mutable {
            if (waitForShutdown(6000)) return;
            onUiThread([uiHandle]() {
              if (uiHandle->get_update_state() == 6) {
                uiHandle->set_update_state(0);
                uiHandle->set_update_available(false);
              }
            });
          });
        }
      }
      if (waitForShutdown(250)) break;
    }
  });

  g_workers.start([uiHandle = ui, &state]() {
    if (waitForShutdown(800)) return;  // hold the centered logo
    onUiThread([uiHandle, &state]() {
      state.phase.store(kPhaseSlide);
      uiHandle->set_phase(kPhaseSlide);
    });
    if (waitForShutdown(950)) return;
    onUiThread([uiHandle, &state]() {
      state.phase.store(kPhaseMain);
      uiHandle->set_phase(kPhaseMain);
      if (uiHandle->get_setting_auto_check_updates()) {
        uiHandle->set_update_state(1);
        uiHandle->set_update_available(true);
        Updater::startCheck();
      } else {
        uiHandle->set_update_state(0);
        uiHandle->set_update_available(false);
      }
    });
  });

  std::atomic<bool> stopScan{false};
  std::thread scanThread([uiHandle = ui, &state, &stopScan]() mutable {
    while (!stopScan.load() && !g_shutdown.stopping()) {
      auto latest = findMinecraftProcesses();
      bool shouldAutoInject = false;
      {
        std::lock_guard<std::mutex> lk(state.mtx);
        state.processes = std::move(latest);
        for (auto it = state.local.begin(); it != state.local.end();) {
          bool present = false;
          for (const auto &mp : state.processes)
            if (mp.pid == it->first) { present = true; break; }
          if (!present) it = state.local.erase(it);
          else ++it;
        }
        for (auto it = state.autoInjectAttempted.begin();
             it != state.autoInjectAttempted.end();) {
          bool present = false;
          for (const auto &mp : state.processes)
            if (mp.pid == *it) { present = true; break; }
          if (!present) it = state.autoInjectAttempted.erase(it);
          else ++it;
        }
        ULONGLONG uptimeMs = GetTickCount64() - state.startTime;
        if (state.phase.load() == kPhaseMain &&
            state.autoInjectEnabled.load() &&
            uptimeMs >= 3500) {
          for (const auto &mp : state.processes) {
            if (mp.injected) {
              state.autoInjectAttempted.insert(mp.pid);
              continue;
            }
            if (state.autoInjectAttempted.count(mp.pid)) continue;
            auto &lr = state.local[mp.pid];
            if (lr.working) continue;
            lr.selected = true;
            state.autoInjectAttempted.insert(mp.pid);
            shouldAutoInject = true;
          }
        }
      }
      if (stopScan.load() || g_shutdown.stopping()) break;
      onUiThread([uiHandle, &state, shouldAutoInject]() mutable {
        publishProcesses(*uiHandle, state);
        if (shouldAutoInject) {
          uiHandle->invoke_inject_clicked();
        }
      });
      if (waitForShutdown(500)) break;
    }
  });

  static std::atomic<bool> s_trayBalloonShown{false};
